INSERT INTO `blogs` (`id`, `user_id`, `betreff`, `inhalt`, `datum`) VALUES
(23, 21, 'Adel und Titel', 'Konsul, Doktor, Professor, Graf, Hoheit, Durchlaucht, Direktor, Spektabilit&auml;t, Magnifizienz, Majest&auml;t, Senator, …Hat mal jemand ein Aspirin f&uuml;r mich?\r<br>Auf diese Art werden wohl viele von uns reagieren, wenn sie mit der fast un&uuml;berschaubaren Anzahl von Titeln konfrontiert werden, die sich Menschen im Laufe der Zeit erdacht haben, um sich vom gew&ouml;hnlichen Sterblichen abzuheben.\r<br>Ohne Zweifel, Titel sind begehrt. Sie versprechen Macht, Ansehen und Prestige. Adelspr&ouml;&szlig;linge, die mit ihrem Titel geboren werden, k&ouml;nnen sich gl&uuml;cklich sch&auml;tzen. Ihnen bleibt die M&uuml;hsaal erspart, die andere aufwenden m&uuml;ssen, um in den Besitz einen Titels zu gelangen. Manche w&auml;hlen die akademische Laufbahn, eine relativ sichere Methode, denn der Weg zum Doktortitel ist streng festgelegt. Einige aus dieser Gruppe gelangen sp&auml;ter zur Professorw&uuml;rde oder werden gar Dekan. Es ist dabei ziemlich egal, welcher Studiengang gew&auml;hlt wird. Sicher sind einige Doktortitel schwerer zu erlangen als andere. F&auml;cher wie Mathematik und Physik fordern strenges logischen Denken und gro&szlig;en Arbeitsaufwand. Oft vernachl&auml;ssigen die Titelanw&auml;rter ihre Familie.\r<br>Aber es geht auch anders. Gewisse Geisteswissenschaftler k&ouml;nnen sich schon allein dadurch zu akademischer W&uuml;rde erheben, indem sie andere zitieren und ihre wilden Gedankeng&auml;nge mit m&ouml;glichst unverst&auml;ndlichen Formulierungen tarnen. Kenner der Materie sind sich bewu&szlig;t, da&szlig; jeder Zweig der Wissenschaften praktisch eine eigene Fachsprache besitzt. Eine vorz&uuml;gliche Strategie, den Einblick in die eigene Arbeitsweise zu verschleiern, bei dem sicher viele Unzul&auml;nglichkeiten sichtbar w&uuml;rden. Insider wissen von einem interessanten Experiment zu berichten. Ein Amerikaner f&uuml;tterte seinen Computer mit einigen Grundregeln der Sprache und des Satzaufbaus sowie einer Menge unverst&auml;ndlicher Fremdw&ouml;rter. Der Rechner erstellte durch zuf&auml;llige Aneinananderreihung ein scheinbar wissenschaftliches Dokument. Das Ergebnis wies eine frappierende &Auml;hnlichkeit mit vielen &uuml;blichen Doktorarbeiten auf.\r<br>Neben der wissenschaftlichen Laufbahn, gibt es die Titelk&auml;ufe. F&uuml;r den Wohlhabenden eine bequeme Sache. Kluge Titelverk&auml;ufer wie Hans Hermann Weyer f&uuml;llen diese Marktnische, die von Eitelkeit und falschen Vorstellungen beherrscht wird.\r<br>Eine andere uns wohlbekannte Methode ist die Technik der progressiven Heirat. Die Hochzeit mit einem oder einer Adeligen ist die einfachste und wahrscheinlich auch die angenehmste Art, einen Titel zu erhalten. H&auml;ufig kann der diese Taktik ausf&uuml;hrende schlaue Fuchs auch mit einem betr&auml;chtlichem Zuwachs seines Verm&ouml;gens rechnen. Leider gibt es auch Nachteile. Die Anzahl der Adelspr&ouml;&szlig;linge ist knapp und die Bewerber sind zahlreich. Ein Grund daf&uuml;r ist der gro&szlig;e Bekanntheitsgrad der progressiven Adelsheirat. So ver&ouml;ffentlichte die Illustrierte Gl&uuml;cksrevue im Juli 1993 eine Liste von adeligen Frauen, die zu diesem Zeitpunkt noch zu haben waren, inclusive Fotos, Bildungs–, Charakter– und Verm&ouml;gensbeurteilungen. Ich kann Ihnen einige dieser Namen nicht vorenthalten: Clothilde d’ Orl&eacute;ons, Bettina Bernadotte, Allessandra Borghese, Sarah Armstrong–Jones. Die Frauen sahen alle ihrem Namen entsprechend gut aus. Es geh&ouml;rt zu den gro&szlig;en Mysterien dieser Welt, warum die Zeitschrift nur Kandidatinnen abdruckte, obwohl ich glaube, da&szlig; sie weitgehend von Frauen gelesen wird.\r<br>Der edelste Weg, an einen Titel zu gelangen ist, wenn dieser ehrenhalber verliehen wird. Menschen, die einen Titel ehrenhalber tragen, haben nicht auf den Titel hin gearbeitet. Fernab von den sicheren Universit&auml;ten und dem Selbstbetrug des Titelkaufs konnten sie durch besondere Leistungen in Technik, Wirtschaft, Humanit&auml;t oder anderen Gebieten auf sich aufmerksam machen und der Allgemeinheit echten Nutzen bringen. Es sollte eigentlich von jederman anerkannt sein, da&szlig; Titeltr&auml;ger ehrenhalber gr&ouml;&szlig;ere Leistungen vollbracht haben, als solche die ihren Titel auf anderen Wegen erstanden haben. In England ist die Erhebung in den Adelsstand nur gr&ouml;&szlig;ten Pers&ouml;nlichkeiten vorbehalten und von unvergleichbarem Prestige. Wie anders ist die Situation in Deutschland. Hier wird ein Titel ehrenhalber gesellschaftlich nur halb anerkannt. Sicher ist daran die Vielzahl der akademischen Neider nicht ganz unschuldig.\r<br>Einer der Tr&auml;ger eines Titel ehrenhalber war Dr. h. c. Ferdinand Ferri Porsche, der nach dem Krieg die Firma Porsche wieder aufbaute und zu neuer Gr&ouml;&szlig;e f&uuml;hrte. Nur wenige Akademiker werden von sich behaupten, ihre Leistungen k&ouml;nnten sich mit den seinen messen. Interessanterweise schien Ferdinand Porsche ein Kenner der Namenstheorie zu sein. Au&szlig;er dem Doktortitel f&uuml;r das gesellschaftliche Ansehen, f&uuml;hrte er einen Spitznamen, der ihn auch im zwischenmenschlichen Bereich nett und sympathisch machte 5. Sp&auml;ter wurde sein Name jedoch so gro&szlig;, da&szlig; er den Glanz des Titels &uuml;berstrahlte und in der Bedeutungslosigkeit verschwinden lie&szlig;. Heute wissen nur die wenigsten, da&szlig; Ferdinand Porsche einen Doktortitel trug.\r<br>Doch was ist wirklich dran am Titel? Welche Vor– und Nachteile bringt er? Unbestritten ist, da&szlig; der Titel auch heute noch als Teil des Namens angesehen wird. Als ich vor kurzem einen Antrag f&uuml;r das Finanzamt ausf&uuml;llen mu&szlig;te, entdeckte ich auch ein Feld f&uuml;r den Titel. Werden Titeltr&auml;ger vom Finanzamt anders behandelt? Tats&auml;chlich genie&szlig;t ein Titeltr&auml;ger eine Reihe von Privilegien. Er kann sich des Respekts und der Achtung seiner Mitmenschen sicher sein. Wenig bekannt ist hingegen, da&szlig; ein Titel allgemeine Autorit&auml;t verleiht, und zwar auch auf Gebieten, die dem Titeltr&auml;ger wenig bekannt sind. In Diskussionen gilt die alte Weisheit, da&szlig; der Titel der Ansicht seines Tr&auml;gers mehr Gewicht verleiht, als das vern&uuml;nftigste Argument.\r<br>Dr. Kaufmann besa&szlig; einen recht m&auml;&szlig;ig erworbenen Doktortitel in Soziologie. In seiner weitgehend unbekannt gebliebenen Arbeit untersuchte er die Arbeitsgewohnheiten von B&uuml;rokraten in Gro&szlig;verwaltungen und entwickelte eine Theorie dar&uuml;ber, warum die Anzahl der Beamten auch dann zunimmt, wenn die Menge der zu verwaltenden Dinge abnimmt.\r<br>Weil auf seinem Fachgebiet wenig zu verdienen war, beschlo&szlig; Dr. Kaufmann seinen Titel auf andere Weise zu nutzen. Er wurde Analyseexperte. Wo immer die sogenannten unabh&auml;ngigen Kommissionen zusammengestellt wurden, um ihre Urteile zu bestimmten Sachlagen abzugeben, erschien der Name von Dr. Kaufmann. Besonderen Erfolg konnte er in Fragen der Verkehrsplanung f&uuml;r sich verbuchen. Der Einflu&szlig; seinen Titels wog immmer schwerer, als die Argumente der Verkehrfachleute, die sich meistens &uuml;ber Jahre mit den Fragen auseinandergesetzt hatten. Der Auswirkungen seiner Arbeit sind noch heute in vielen St&auml;dten zu beobachten. Dr. Kaufmann setzte sich im Alter von 50 Jahren zur Ruhe. Seine Freizeit verbringt er auf einem Golfplatz, der sich wunderbar in das angrenzende Naturschutzgebiet einf&uuml;gt.\r<br>Es darf auch nicht vergessen werden, da&szlig; Titel eine hervorragende M&ouml;glichkeit darstellen, den Weg in die Vorst&auml;nde gro&szlig;er deutscher Unternehmen zu beschreiten. Sowohl das von, als auch der Doktortitel sind beliebt. Das ein von nichts &uuml;ber die Qualifikation aussagt, ist klar. Bei einem Doktortiteln gilt, wie im Fall von Dr. Kaufmann, da&szlig; es ziemlich egal ist, wie und auf welchem Gebiet er erworben wurde. So gibt es dann auch in den Vorst&auml;nden Ingenieure, Philosophen und Juristen. Wirtschaftsexperten scheinen eher selten zu sein. Eine genaue Analyse wird durch die Tatsache erschwert, da&szlig; in den meisten Ver&ouml;ffentlichungen nur der Doktortitel, nicht aber das Fachgebiet erw&auml;hnt wird. Ist bei diesen Herren 6 eine gewisse Scheu vor der Wahrheit vorhanden?\r<br>H&auml;ufig besitzen Vorstandsmitglieder mehrere Doktortitel. Ich f&uuml;hle mich dann immer an den Fall des Studenten Alois Hellbier erinnert, der lange Zeit in einer Wohngemeinschaft lebte. Damit er wu&szlig;te, wann er Besuch bekam, stand auf seinem Klingelschild Dr Dr Dr Hellbier. Damit war gemeint: Alois Hellbier, bitte dreimal klingeln. Insider sprechen seitdem bei Doktortiteln oft von Klingelnamen. Mitarbeiter der Firma Radiant Research, die gute Kontakte zur akademischen Welt pflegen, erw&auml;hnen h&auml;ufig die Zusammenarbeit mit den Klinggl&ouml;ckchen.\r<br>Au&szlig;erdem stellt ein Titel durch seine distanzierende Wirkung einen psychologischen Schutz dar. Unter der Maske eines Titels lassen sich bequem die eigenen Namensprobleme verstecken.\r<br>Obwohl es eine Pflicht der H&ouml;flichkeit ist, einen Titeltr&auml;ger mit seinem Titel anzureden, mu&szlig; es im ausgehenden zwanzigsten Jahrhundert erlaubt sein, die Frage zu stellen, ob dieses Verhalten sinnvoll ist. Aus historischer Sicht entstand diese Form der Anrede auf der Grundlage der Feudalherrschaft. Folglich war die Titelanrede nicht der Ausdruck des ehrlich gemeinten Respekts, sondern eine Zwangsma&szlig;nahme der Feudalherren. Die Geschichte liefert also keinen Grund, diese Anredeform auch noch heute fortzusetzen. Adelige werden meisten mit ihrem Titel geboren. Daf&uuml;r geb&uuml;hrt ihnen keinerlei Respekt. Nicht umsonst kennt der Volksmund den Spruch Ein freies und fr&ouml;hliches Leben kennen nur F&uuml;rsten, Pfaffen und Piraten.\r<br>Menschen, die ihren Titel durch Arbeit erworben haben, teilen sich in drei Gruppen. Mitglieder der ersten Gruppe legen auf ihren Titel keinen besonderen Wert. Wenn sie einen solchen Titeltr&auml;ger kennen, werden sie von seinem Titel wahrscheinlich aus der sozialen Umgebung erfahren haben.\r<br>Die Angeh&ouml;rigen der zweiten Gruppe nutzen ihren Titel als psychologischen Schutz und sind im hohen Ma&szlig;e auf ihn angewiesen. Da der Titel in solchen F&auml;llen die seelische Weiterentwicklung der Betreffenden behindert, sollte in der Anrede auf den Titel verzichtet werden.\r<br>Die dritte Gruppe nutzt den Titel aus rein praktischen Gr&uuml;nden. Dazu geh&ouml;ren viele &Auml;rzte, bei denen der Titel z. B. im Telefonbuch steht, damit sie im Notfall von Patienten schneller gefunden werden. Der Doktortitel st&auml;rkt au&szlig;erdem das Vertrauen des Patienten in seinen Arzt. Es gibt auch Menschen, die den Titel nutzen, um damit an Vorteile finanzieller oder anderer Art zu kommen. Bei den Praktikern kann die Titelanrede also je nach Situation durchaus angebracht sein.\r<br>Rein verstandesm&auml;&szlig;ig ist zu sagen, da&szlig; es fast nie einen Grund gibt, die Titelanrede zu gebrauchen, au&szlig;er sie gew&auml;hrt Ihnen finanzielle, politische oder pers&ouml;nliche Vorteile. Menschen mit einem gesunden Selbstbewu&szlig;tsein wissen sich auch ohne Titel zu sch&auml;tzen. Falls Sie selbst zu den Titeltr&auml;gern geh&ouml;ren, sollten Sie nicht auf die Vorteile verzichten, die Ihnen ein Titel bringt. &Ouml;ffentliche Ablehnung Ihres Titels zeugt von Dummheit oder Idealismus. Vergessen Sie aber niemals, da&szlig; viele Menschen Gro&szlig;artiges vollbracht haben, ohne daf&uuml;r mit einem Titel belohnt worden zu sein.\r<br>Bei Adeligen kann der Titel eine von vielen unerw&uuml;nschte Wirkung besitzen. Sie stehen tagt&auml;glich im Licht der &Ouml;ffentlichkeit. Die Regenbogenpresse l&auml;&szlig;t keine M&ouml;glichkeit aus, die kleinsten Geschehnisse aus dem Privatleben gro&szlig;formatig zu pr&auml;sentieren. Ein gl&uuml;ckliches und sorgenfreies Leben ist unter diesen Umst&auml;nden nur schwer zu f&uuml;hren. Manche selbstlosen Helfer versuchen hier Abhilfe zu schaffen, indem sie mit Fernsehserien wie Lindenstra&szlig;e die Aufmerksamkeit des Publikums auf nicht wirklich existierende Personen lenken.\r<br>Es soll aber nicht verschwiegen werden, da&szlig; ein Adels– oder sonstiger Titel die Chancen Heiratswilliger betr&auml;chtlich erh&ouml;hen kann. Titeltr&auml;ger sind als lebendes Prestigeobjekt hei&szlig; begehrt. Hier stellt sich mit Recht die Frage, ob es moralisch rechtm&auml;&szlig;ig sein kann, wenn z. B. ein junger Mann seiner Angebeteten einen Titel vort&auml;uscht, um ihr Herz zu gewinnen. Ich meine Nein, denn dieses Vorgehen stellt eine ernste Gefahr f&uuml;r die Technik der progressiven Heirat dar. Wom&ouml;glich w&uuml;rden beide in ihr Ungl&uuml;ck laufen.\r<br>Andreas M&ouml;ller fand eine ebenso elegante wie moralisch einwandfreie Alternative. Seine Angebetete Mara, die Gr&auml;fin von Kusenbaum, hielt sich ausschlie&szlig;lich in Adelskreisen auf. Um akzeptiert zu werden, stellte sich Andreas stets mit „Gestatten, Andreas M&ouml;ller von Quakenbr&uuml;ck.“ vor, womit er in etwas schlampigem Deutsch ausdr&uuml;cken wollte, da&szlig; seine Heimatstadt Quakenbr&uuml;ck sei. Die Rechnung ging auf und es kam zur Heirat. Die Ehe wurde jedoch nicht gl&uuml;cklich, weil Mara und Andreas die v&ouml;llig verschiedenen Weltansichten aus ihren Schichten beibehielten. Die beiden trennten sich nach vier Jahren im gegenseitigen Einverst&auml;ndnis.\r<br>Titel gelten auch als eine Dom&auml;ne von Heiratsschwindlern und Trickbetr&uuml;gern, weil blaues Blut gut geeignet ist, da&szlig; Vertrauen von blau&auml;ugigen B&uuml;rgern zu erschleichen. Seien Sie vorsichtig! So mancher Gauner w&uuml;rde Ihre berechtigte Hoffnung auf eine progressive Heirat schamlos ausnutzen.\r<br>Ein titel&auml;hnliches Prestige kann mit der sorgf&auml;ltigen Auswahl eines Namens erreicht werden. Lange klangvolle Namen k&ouml;nnen ebenso edel und anspruchsvoll wirken. So ein Fall konnte im Juli 93 im Werbefernsehen beobachtet werden, als Vanessa Meier–Bl&ouml;nkeberg das sahnige Geheimnis von Philadelphia entdeckte. Kenner werden vermuten, da&szlig; dieser Name durch progressive Heirat entstand.\r<br>\r<br>Wenn man die Positionen der Klopapierhalter in deutschen Badezimmern betrachtet, kommt man unwillk&uuml;rlich zu dem Schlu&szlig;, da&szlig; s&auml;mtliche Installateure als Schlangenmenschen im Zirkus auftreten k&ouml;nnten.', '2012-10-23 19:42:53'),
(24, 22, 'Was ist eine Ananas?', 'Die Ananas (Ananas comosus respektive Ananas sativus) ist eine Pflanzenart aus der Familie der Bromeliengew&auml;chse (Bromeliaceae). Sie ist urspr&uuml;nglich in Amerika heimisch und wird heute weltweit in den tropischen Gebieten als Obstpflanze angebaut. Sie bildet fleischige Fruchtst&auml;nde, die frisch verzehrt oder zu Konserven und Saft verarbeitet werden.\r<br>Das Wort Ananas entstammt der Bezeichnung nan&aacute; der Frucht in der Guarani-Sprache. Das Art-Epitheton comosus stammt aus dem Lateinischen und bedeutet „schopfig“, was auf den Blattschopf am oberen Ende des Fruchtstandes anspielt.', '2012-10-24 16:28:48'),
(25, 22, 'Melone', 'Als Melone bezeichnet man vor allem in subtropischen Gebieten kultivierte Gew&auml;chse mit gro&szlig;en, saftreichen Beeren-Fr&uuml;chten (botanischen Gem&uuml;sen). Sie geh&ouml;ren zur Familie der K&uuml;rbisgew&auml;chse (Cucurbitaceae), werden also genau genommen als Gem&uuml;se bezeichnet. Der deutsche Name ist von dem griechischen Wort &amp;#956;&amp;#942;&amp;#955;&amp;#959; (M&amp;#275;lo), ‚Apfel‘ abgeleitet. Es wird haupts&auml;chlich zwischen Zuckermelonen und Wassermelonen unterschieden.\r<br>Melonen werden in der Botanik nicht als Verwandtschaftsgruppe angesehen, die Zuckermelonen (Cucumis melo) sind enger mit den Gurken verwandt als mit den Wassermelonen (Citrullus lanatus).\r<br>Die Frucht wird aufgrund der harten Schale als Panzerbeere bezeichnet.', '2012-10-24 16:43:38'),
(26, 22, 'Apfel', 'Die &Auml;pfel (Malus) bilden eine Pflanzengattung der Kernobstgew&auml;chse (Pyrinae) aus der Familie der Rosengew&auml;chse (Rosaceae). Die Gattung umfasst etwa 42 bis 55 Arten laubwerfender B&auml;ume und Str&auml;ucher aus W&auml;ldern und Dickichten der n&ouml;rdlichen gem&auml;&szlig;igten Zone in Europa, Asien und Nordamerika, aus denen auch eine gro&szlig;e Anzahl an oft schwer unterscheidbaren Hybriden hervorgegangen ist.\r<br>Die weltweit mit Abstand bekannteste und wirtschaftlich sehr bedeutende Art ist der Kulturapfel (Malus domestica). Daneben werden manche aus Ostasien stammende Arten mit nur etwa kirschgro&szlig;en Fr&uuml;chten, wie etwa der Japanische Apfel (Malus floribunda), der Kirschapfel (Malus baccata) und Malus &times;zumi in gem&auml;&szlig;igten Klimagebieten als Zierstr&auml;ucher und -b&auml;ume angepflanzt. Nicht zu verwechseln mit den &Auml;pfeln sind die nicht n&auml;her verwandten Granat&auml;pfel (Punica granatum).', '2012-10-24 16:44:14'),
(27, 22, 'Banane', 'Die Bananen (Musa) sind eine Pflanzengattung in der Familie der Bananengew&auml;chse (Musaceae) innerhalb der Einkeimbl&auml;ttrigen Pflanzen (Monokotyledonen). In der Gattung gibt es rund 100 Arten. Einige Arten und Hybriden bilden essbare Fr&uuml;chte, von denen diejenigen der Dessertbanane (Musa &times; paradisiaca) zum Teil f&uuml;r die Nahrungsmittelproduktion angebaut werden. Die essbaren Fr&uuml;chte haben, verglichen mit anderen Obstsorten, einen m&auml;&szlig;igen Vitamingehalt (Vitamin C (12 mg pro 100 g), Fols&auml;ure (20 &micro;g pro 100 g)), und enthalten Mineralstoffe (insbes. viel Kalium und Magnesium, Phosphor, Eisen, Mangan, Kupfer), Zucker sowie Ballaststoffe.', '2012-10-24 16:44:46'),
(28, 22, 'Sauerkirsche', 'Die Sauerkirsche oder Weichselkirsche, in &Ouml;sterreich und der Schweiz oft kurz Weichsel genannt, (Prunus cerasus) ist eine Pflanzenart aus der Familie der Rosengew&auml;chse (Rosaceae). Sie wird als Obstbaum genutzt.', '2012-10-24 16:45:06'),
(29, 22, 'Feige', 'Die Echte Feige (Ficus carica) ist eine Pflanzenart aus der Gattung der Feigen (Ficus). Sie z&auml;hlt zu den &auml;ltesten domestizierten Nutzpflanzen und wird im gesamten Mittelmeergebiet angebaut. Sie hat wie alle Feigen eine komplexe Best&auml;ubungs&ouml;kologie.', '2012-10-24 16:45:24'),
(30, 24, 'Parteien einigen sich auf neues Wahlrecht', 'Die Bundestagsfraktionen von Union, FDP, SPD und Gr&uuml;nen haben sich auf ein neues Wahlrecht verst&auml;ndigt. Danach sollen die sogenannten &Uuml;berhangmandate durch Ausgleichsmandate neutralisiert werden. Das teilte der Parlamentarische Gesch&auml;ftsf&uuml;hrer der Unionsfraktion im Bundestag, Michael Grosse-Br&ouml;mer, in Berlin mit.\r<br>\r<br>Das neue Modell l&auml;uft darauf hinaus, dass die Parteien, die weniger oder keine &Uuml;berhangmandate gewonnen haben, zum Ausgleich genau so viele Mandate zugestanden bekommen, dass die urspr&uuml;nglichen Mehrheitsverh&auml;ltnisse wieder hergestellt sind. Folge d&uuml;rfte eine Vergr&ouml;&szlig;erung des Parlaments sein.', '2012-10-24 16:50:53'),
(31, 24, 'Bundestagswahl in den Herbstferien?', 'Zwischen Bundesregierung und Opposition bahnt sich ein Streit &uuml;ber den Termin der Bundestagswahl 2013 an. Die CSU w&uuml;nscht, dass zwischen der bayerischen Landtagswahl und der Abstimmung im Bund zwei Wochen liegen. Die Bundestagswahl m&uuml;sste dann am 29. September 2013 stattfinden.\r<br>\r<br>  \r<br>Die n&auml;chste Bundestagswahl muss zwischen dem 28. August und dem 27. Oktober 2013 erfolgen.\r<br>Dagegen legt die SPD Protest ein, da in den von ihr regierten Bundesl&auml;ndern Hamburg, Berlin und Brandenburg dann die Herbstferien beginnen. Offensichtlich sei in der Regierung nach der Nominierung von Peer Steinbr&uuml;ck zum SPD-Kanzlerkandidaten &quot;die reine Panik ausgebrochen&quot;, sagte Parteichef Sigmar Gabriel der &quot;S&uuml;ddeutschen Zeitung&quot;. Anders sei &quot;nicht zu erkl&auml;ren, dass Union und FDP ernsthaft erw&auml;gen, den Termin f&uuml;r die Bundestagswahl in die Ferienzeit von drei SPD-regierten Bundesl&auml;ndern zu legen&quot;. Die CSU str&auml;ube sich deshalb gegen einen gemeinsamen Termin f&uuml;r Bundes- und Landtagswahl, weil sie die Illusion habe, sich &quot;vom absehbaren Absturz der schwarz-gelben Bundesregierung abkoppeln&quot; zu k&ouml;nnen, kritisierte Gabriel.\r<br>\r<br>&quot;Kein Annex zur Bundestagswahl&quot;\r<br>\r<br>In Bayern wird h&ouml;chstwahrscheinlich am 15. September n&auml;chsten Jahres ein neuer Landtag gew&auml;hlt. Auf diesen Termin hatten sich die Koalitionspartner CSU und FDP nach einem Bericht der dpa vor einigen Wochen verst&auml;ndigt. Die Bundestagswahl solle m&ouml;glichst mit zwei Wochen Abstand stattfinden. Ein Sprecher der M&uuml;nchner Staatskanzlei sagte: &quot;Die bayerische Landtagswahl kann kein Annex zur Bundestagswahl sein.&quot; Damit m&uuml;sste der neue Bundestag am 29. September gew&auml;hlt werden.', '2012-10-24 16:52:45'),
(33, 24, 'Zweifel an m&ouml;glicher Feuerpause in Syrien', 'Am wichtigsten islamischen Feiertag sollen in Syrien die Waffen ruhen: Nach Angaben des UN-Sondergesandten Lakhdar Brahimi ist die Regierung in Damaskus zu einer mehrt&auml;gigen Feuerpause w&auml;hrend des islamischen Opferfests Eid al-Adha bereit, das am Freitag beginnt.\r<br>\r<br>Regierung will Donnerstag entscheiden\r<br>\r<br>Doch von offizieller syrischer Seite wurde das nicht best&auml;tigt: Eine Entscheidung &uuml;ber eine Waffenruhe werde erst am Donnerstag getroffen, teilte das syrische Au&szlig;enministerium mit. Brahimi betonte jedoch, er rechne mit dem Zustandekommen.\r<br>\r<br>Syrische Oppositionelle zweifeln am Willen der Regierung, eine Waffenruhe umzusetzen. &quot;Syriens Regime ist nicht ehrlich&quot;, sagte der Sprecher des oppositionellen Syrischen Nationalrats (SNC), George Sabra. Im Fr&uuml;hjahr war eine von Brahimis Vorg&auml;nger Kofi Annan vereinbarte Waffenruhe bereits nach wenigen Tagen gebrochen worden.', '2012-10-24 16:53:40'),
(34, 24, 'Hannover dreht Partie in Unterzahl', 'Der Fu&szlig;ball-Bundesligist feierte trotz der fr&uuml;hen Roten Karte von Verteidiger Karim Haggui (9. Minute) einen 2:1 (1:1)-Sieg gegen UD Levante. Szabolcs Huszti (21.) per Handelfmeter und Didier Ya Konan (49.) sorgten mit ihren Toren f&uuml;r den Erfolg vor 34 600 Zuschauern am Donnerstagabend (04.10 2012). &quot;Das war ein wichtiger Schritt. Es war nach dem Elfmeter und dem Platzverweis schwierig, aber wir sind gut zur&uuml;ck gekommen. Das zeichnet uns aus&quot;, sagte 96-Profi Lars Stindl. &quot;Es war sch&ouml;n zu sehen, dass wir uns nicht aufgegeben haben&quot;, sagte Nationaltorh&uuml;ter Ron-Robert Zieler und freute sich &uuml;ber die nun gute Ausgangsposition: &quot;Wir m&uuml;ssen jetzt weiter die Heimspiele gewinnen und zusehen, dass wir ausw&auml;rts punkten.&quot;', '2012-10-24 16:56:26'),
(35, 24, 'Stuttgart blamiert sich in Molde', 'F&uuml;nf Tage nach dem ersten Saisonsieg in der Fu&szlig;ball-Bundesliga ist der VfB Stuttgart unsanft auf dem Boden der Tatsachen gelandet. Der defensiv erneut anf&auml;llige VfB blamierte sich im Nebengesch&auml;ft Europa League nach einer fahrl&auml;ssigen Vorstellung durch eine 0:2 (0:0)-Niederlage beim norwegischen Meister Molde FK. Die Tore erzielten Jo Inge Berget per Kopf (58.) und Daniel Chima (87.).\r<br>\r<br>&quot;Wir haben extrem geschludert bei der Chancenverwertung. Da gewinnst du auf europ&auml;ischem Niveau kein Spiel, das ist klar. Die Effizienz ist uns fl&ouml;ten gegangen&quot;, schimpfte VfB-Sportdirektor Fredi Bobic. Auf Trainer Bruno Labbadia kommt viel Arbeit zu. Molde-Coach Ole Gunnar Solskjaer konnte sein Gl&uuml;ck unterdessen kaum fassen. &quot;Das war eine der besseren Abende in der Clubgeschichte. Ich bin sehr stolz''&quot;, analysierte er.\r<br>\r<br>Nach dem 2:2 gegen Steaua Bukarest im ersten Gruppenspiel wartet Stuttgart damit weiter auf den ersten Dreier in der Europapokal-Saison. Vor dem Liga-Duell am Sonntag mit Bayer Leverkusen steht die Mannschaft von Trainer Bruno Labbadia trotz des Erfolgs am vergangenen Wochenende beim 1. FC N&uuml;rnberg (2:0) damit weiter geh&ouml;rig unter Druck.', '2012-10-24 16:57:09'),
(36, 24, 'Europa braucht Bankenunion', 'Heute ist EZB-Chef Mario Draghi in Berlin, um die Abgeordneten von der Richtigkeit seines Kurses in Sachen Euro-Rettung zu &uuml;berzeugen, gestern erkl&auml;rte Bundesfinanzminister Wolfgang Sch&auml;uble, dass er nicht sicher sei, ob der H&ouml;hepunkt der Krise schon &uuml;berstanden ist und der Dax verlor gestern mehr als zwei Prozent.', '2012-10-24 16:57:53'),
(37, 22, 'Draghis Bes&auml;nftigungstour im Bundestag', 'EZB-Pr&auml;sident Mario Draghi hat die Krisenstrategie der Notenbank verteidigt. Bei einer gemeinsamen Sitzung mehrerer Bundestagsaussch&uuml;sse rechtfertigte er gegen&uuml;ber den Abgeordneten insbesondere das Programm zum unbegrenzten Aufkauf von Staatsanleihen der Krisenstaaten.\r<br>\r<br>Die EZB halte sich streng an ihr Mandat. Sie werde ausschlie&szlig;lich Staatsanleihen von Investoren auf dem Sekund&auml;rmarkt kaufen, die bereits vor einiger Zeit ausgegeben worden waren. Auf dem Prim&auml;rmarkt werde die Notenbank dagegen keine Papiere kaufen - also nicht direkt bei der Ausgabe der Anleihen durch die Regierungen. Damit bewege sie sich innerhalb des Mandats, das die direkte Staatsfinanzierung verbietet.', '2012-10-24 16:59:55'),
(38, 22, 'Richtungssuche im DAX geht weiter', 'Vor wichtigen Konjunkturdaten aus den USA d&uuml;rfte ein neuer Aufw&auml;rtsimpuls an den B&ouml;rsen auf sich warten lassen. Um 16 Uhr werden Angaben zum US-Immobilienmarkt ver&ouml;ffentlicht. Zudem warten Anleger auch gespannt auf Aussagen der US-Notenbank am Abend. Die W&auml;hrungsh&uuml;ter werden nach Ansicht der Mehrzahl der Analysten den Leitzins auf dem historisch niedrigen Niveau belassen und den expansiven geldpolitischen Kurs der Fed noch einmal best&auml;tigen.', '2012-10-24 17:01:03'),
(39, 22, 'Handeln Sie noch?', 'Viele Privatanleger trauen sich derzeit nicht an die B&ouml;rse, obwohl die Kurse der meisten Aktienm&auml;rkte, auch hierzulande, seit Anfang Juni kr&auml;ftig gestiegen sind. Was machen Sie, handeln Sie noch oder streiken Sie?', '2012-10-24 17:01:35'),
(40, 22, 'Kann Facebook das Ruder noch rumrei&szlig;en?', 'Die Aktie des sozialen Netzwerks Facebook hat nach Quartalszahlen einen respektablen Satz nach oben gemacht. Das Plus von knapp 13 Prozent sch&uuml;rt Hoffnungen: Hat die Facebook-Aktie endlich ihren Boden gefunden? [mehr]', '2012-10-24 17:02:39'),
(41, 24, 'README PLEASE', '.README-Datei\r<br>\r<br>\r<br>1. Aufrufen der URL www.unser-source.co.de\r<br>\r<br>2. Registrierung mit Nickname, E-Mail Adresse und Passwort bzw. Login nach bereits \r<br>   durchgef&uuml;hrter Registrierung\r<br>   -&gt; Bitte beachten: E-Mail mit Best&auml;tigungslink kann im Spam- bzw. Junk-E-Mail Ordner landen\r<br>\r<br>3. Best&auml;tigung des per E-Mail versendeten Best&auml;tigungslinks\r<br>\r<br>4. Funktionen\r<br>	- Home: Auflistung der Blogeintr&auml;ge von den abonnierten Usern\r<br>	- Blog: Auflistung der eigenen Blogeintr&auml;ge und M&ouml;glichkeit zur Verfassung weiterer Eintr&auml;ge\r<br>	- Profil: Aufstellung der pers&ouml;nlichen Daten und M&ouml;glichkeit zur &Auml;nderung\r<br>	- Suche: Suche nach anderen Usern und Option einen anderen User zu abonnieren\r<br>	- zu allen Blogeintr&auml;gen k&ouml;nnen KOmmentare verfasst werden', '2012-10-24 17:44:37'),
(42, 23, 'Ich trinke Blut, ist das gut?', 'Ich Merke Schon Lange Dass Ich Das Sonnenlicht Hasse! Es Brennt In Meinen Augen Und Ich F&uuml;hle Mich Unwohl!\r<br>Daher Verbringe Ich Den Tag Meistens Im Haus Oder Schlafe Tags&uuml;ber! An Meinem Arbeitsplatz Ist Es Auch Dunkel Ich Liebe Die Dunkelheit Mit Ihren Vielen Sch&ouml;nen Sternen Und Dem Mond!\r<br>Was Mir Auch Auff&auml;llt Ist Das Meine Geruchs-,Seh- Und H&ouml;rorgane Sehr Gut Ausgebildet Sind!!!\r<br>Ich H&ouml;re Jedes Ger&auml;usch Wenn Ich schlafe!!!\r<br>Und Ich Trinke Gerne Blut.\r<br>Das Ist Kein Spa&szlig;.\r<br>Das Von Tieren.\r<br>Von Mir.\r<br>Ich Bin Kein Vampir, So Was Gibt Es nicht. Aber Ich Habe Angst.\r<br>Vor Mir. Um Meine Mitmenschen.', '2012-10-25 12:23:32'),
(43, 23, 'Foltermethoden (Teil 1) - Das Pf&auml;hlen', 'Hinrichtung. Das Pf&auml;hlen gilt als eine der grausamsten Hinrichtungen, die den Tod des Opfers zur Folge hat.\r<br>Dem Verurteilten wurde ein angespitzter, oder absichtlich stumpf gelassener, und mit Fett beschmierter Pfahl anal eingef&uuml;hrt. Nicht, dass das schon schmerzhaft genug w&auml;re, wurde dieser Pfahl aufgestellt mit dem Opfer obenauf, das durch sein eigenes Gewicht immer tiefer rutschte und so den Pfahl immer weiter in seine Eingeweide eindringen lie&szlig;.\r<br>Diese schmerzhafte Prozedur konnte tagelang dauern, bis endlich der erl&ouml;sende Tod eintrat.', '2012-10-25 12:27:34'),
(44, 23, 'Foltermethoden (Teil 2) - Der Scheiterhaufen', 'Ebenfalls Hinrichtung.\r<br>Wird haupts&auml;chlich mit Hexenverbrennung in Verbindung gebracht, aber auch andere &quot;Ketzer&quot; wurden auf dem Scheiterhaufen verbrannt. Dazu wurden die Menschen an einen Pfahl &uuml;ber schnell brennbarem Material, wie d&uuml;nne &Auml;ste und Heu, angebunden und das Feuer wurde entfacht.\r<br>Wer Gl&uuml;ck hatte, dem Band der Henker (manchmal aus Mitgef&uuml;hl oder weil er bezahlt wurde) das Seil so fest um den Hals, dass er schon vor der Verbrennung an Erstickung oder gar Halsbruch starb.', '2012-10-25 12:28:29'),
(45, 23, 'Foltermethoden (Teil 3) - Die Beinschraube', 'Leibesstrafe oder Folter.\r<br>Dieses Ger&auml;t war meistens in den ersten Folterphasen in Gebrauch. Dem Gefolterten wurde die Beinschraube um die Beine gelegt und mithilfe eines Gewindes immer fester zugeschraubt, bis das gew&uuml;nschte Gest&auml;ndnis geliefert wurde. Kam es nicht zum Gest&auml;ndnis, wurden die Schrauben so feste zugedreht, bis starke Quetschungen an den Beinen entstanden und die Knochen zerbrachen.\r<br>\r<br>Zur Verst&auml;rkung wurden die Beinschrauben an die Knie gelegt und so feste zugedreht, dass die Kniegelenke brachen und es zu Splitterbr&uuml;chen kam. Wenn alles kein Gest&auml;ndnis brachte, Schlug man zus&auml;tzlich noch mit einem Hammer darauf.', '2012-10-25 12:29:21'),
(46, 23, 'Foltermethoden (Teil 4) - Die Ziege', 'Folter.\r<br>Klingt harmlos, ist aber eine ungeheuerliche Tortur. Das Opfer wurde eingespannt und seine Fu&szlig;sohlen mit Salz eingerieben. Da Ziegen eine raue Zunge haben, wurde aus dem anf&auml;nglichen Kitzeln ein starkes Brennen. Dass immer wieder erneut Salz auf die Fusssohlen geschmiert wurde, verst&auml;rkte das Brennen. Diese Prozedur wurde so lange durchgef&uuml;hrt, bis der Angeklagte gest&auml;ndig wurde. Gestand er nicht, so f&uuml;hrte das Lecken der Ziege und das Salz bald dazu, dass die Haut sich abl&ouml;ste und unter schrecklichem Brennen die Fu&szlig;sohlen offenlagen.', '2012-10-25 12:30:55'),
(47, 23, 'Foltermethoden (Teil 5) - Die Wasserfolter', 'Folter.\r<br>Hierbei wurde der Angeklagte auf einen Pflock, ein Brett oder einen Tisch gespannt mit dem Bauch nach oben und musste Unmengen von Fl&uuml;ssigkeiten trinken. Der Mund wurde mit einer Zange offen gehalten. Der Henkersknecht fl&ouml;&szlig;te ihm die Fl&uuml;ssigkeiten ein. Damit das Opfer gest&auml;ndig wurde, lie&szlig; man den Beschuldigten mit dem Kopf nach unten drehen, so dass die Fl&uuml;ssigkeit im Magen auf Herz und Lunge dr&uuml;ckten und so Erstickungsgefahr bestand. 6 Liter bei der kleinen und 12 Liter bei der gro&szlig;en Wasserfolter. Dabei erstickten die Opfer oder ihre Blase platzte, wenn After und Harnr&ouml;hre verschlossen waren.', '2012-10-25 12:31:48'),
(48, 27, 'Ein bisschen Philosophia', 'Es gibt Tage im Leben, da fragt man sich, weshalb die Erde, samt Mond, um die Sonne kreist… und worum diese sich wiederum bewegt. Wissenschaftler gehen von einem extrem gro&szlig;en gigantischen schwarzen Loch in der Mitte unseres Sonnensystems aus, was uns alle innerhalb der n&auml;chsten  x-Milliarden Jahre verschlucken wird…\r<br>…Deshalb sollte man sich, meiner Meinung nach, anstatt sein eigenes Unwissen mit der Anfangsfrage zu strapazieren, fragen: Ist es &uuml;berhaupt verantwortlich Kinder in die Welt zu setzen?', '2012-10-25 15:26:42'),
(49, 27, 'WIESOOOOOOO NUR????', 'Wieso m&uuml;ssen die schwarzen B&auml;nder an den gelben S&auml;cken so schnell rei&szlig;en? Da bezahlt man mit jedem Tetrapack und anderen Gr&uuml;nen-Punkt-Produkten schon f&uuml;r unsere M&uuml;llentsorgung und zahlt als artiger B&uuml;rger (p&uuml;nktlich) seine M&uuml;llgeb&uuml;hren…. Und was passiert?  Man wird mit versauten Jeans bestraft, sobald man den Plastem&uuml;ll direkt bis vor der M&uuml;llm&auml;nner Schuhspitzen bringen m&ouml;chte…\r<br>…Was braucht die Gesellschaft noch um endlich wachger&uuml;ttelt zu werden?', '2012-10-25 15:27:19'),
(50, 27, 'M&auml;nner im Haushalt', 'Ich staune immer wieder wie unbeholfen sich einige M&auml;nner, und die, die es werden wollen, im Haushalt anstellen:\r<br> Aus jedem Tischabwischen wird ein Drama, bestehend aus mehreren Akten. Nachdem in der Exposition der Lappen in die richtige Position gebracht wurde, ist das retardierende Moment in der Zeitspanne zu finden, in der, sich eventuell angesammelte Kr&uuml;mel, vom Tisch in den Lappen bef&ouml;rdert werden… Der Schluss eines Dramas, die Katastrophe, geschieht dann kurz vor dem Sp&uuml;lbecken.', '2012-10-25 15:27:56'),
(51, 28, 'Prinzessin Lillifee und das kleine Einhorn', 'Immer wieder hat Prinzessin Lillifee diesen seltsamen Traum. Irgendetwas bedroht ihre Einhorn-Freundin Rosalie. Und eines nachts bittet Rosalie Lillifee im Traum sogar, auf ihr Fohlen Lucy aufzupassen. Als Lillifee am n&auml;chsten Morgen aufwacht, kann sie ihren Augen zuerst nicht trauen. Tats&auml;chlich liegt Lucy bereits in ihrem Bett.', '2012-10-25 16:06:55'),
(52, 28, 'BVB besiegt beste Mannschaft der Welt', 'In der Bundesliga hinkt Dortmund den Zielen hinterher. In der Champions League aber ist dem BVB nun ein grandioser Sieg gegen Real Madrid gegl&uuml;ckt. F&uuml;r den Mann des Tages war er eine besondere Genugtuung.\r<br>So hart kann nur der Fu&szlig;ball sein. Gerade haben die Dortmunder einen ihrer s&uuml;&szlig;esten Momente der j&uuml;ngeren Vereinsgeschichte erlebt, schon m&uuml;ssen sie wieder hinabsteigen aus der so sagenhaft sch&ouml;nen Glitzerwelt der Champions League in die f&uuml;r sie so graue Realit&auml;t der Bundesliga. Am Mittwochabend ist dem BVB dort oben in der K&ouml;nigsklasse ein grandioser und nur in den sch&ouml;nsten Tr&auml;umen f&uuml;r m&ouml;glich gehaltener Heimsieg gegen Real Madrid gelungen; die Borussia, die ja in der Liga ganz und gar nicht gut in die Saison gestartet ist, hat international ein fabelhaftes Signal gesetzt: Mit diesem Club ist zu rechnen, das wei&szlig; man nun. Doch jetzt ist erst Mal Alltag angesagt, im Breisgau, in Freiburg. Und daf&uuml;r erhofft sich der BVB nun eine Menge R&uuml;ckenwind vom europ&auml;ischen Gl&uuml;cks- und Emotionsmoment.\r<br>...\r<br>Dortmund schl&auml;gt Real Madrid in der Champions League: Klopp tritt wegen BVB-Held Schmelzer gegen L&ouml;w nach - weiter lesen auf FOCUS Online: http://www.focus.de/sport/fussball/championsleague/dortmund-schlaegt-real-madrid-in-der-champions-league-klopp-tritt-wegen-bvb-held-schmelzer-gegen-loew-nach_aid_845909.html', '2012-10-25 16:08:23'),
(53, 28, 'Der Termin f&uuml;r die n&auml;chste Zeitumstellun', 'Seit dem 25.03.2012 befinden wir uns in der Sommerzeit. \r<br>Dabei wurde die Uhr um 1 Stunde von 2 auf 3 Uhr vorgestellt, &quot;die Nacht war 1 Stunde k&uuml;rzer&quot;.\r<br>Die n&auml;chste Zeitumstellung ist am:\r<br>Sonntag den 28.10.2012 um 3:00 Uhr.\r<br>Die Uhr wird dann um 1 Stunde zur&uuml;ckgestellt, &quot;die Nacht ist also 1 Stunde l&auml;nger&quot;. Dabei findet der Wechsel von der Sommerzeit in die Winterzeit (Normalzeit) statt.', '2012-10-25 16:10:01'),
(55, 34, 'ICH', 'Der kleine Maulwurf ist eine tschechische Zeichentrickserie. Sie wurde 1957 vom Prager Zeichner Zden&amp;#283;k Miler erschaffen.\r<br>Miler suchte f&uuml;r einen Film &uuml;ber die Verarbeitung von Flachs nach einer Zeichentrickfigur und stolperte, der Legende zufolge, &uuml;ber einen Maulwurfsh&uuml;gel. So entstand der Film Wie der Maulwurf zu seinen Hosen kam, mit dem Miler den Silbernen L&ouml;wen in Venedig gewann. Die besten Freunde des kleinen Maulwurfs sind der Hase, der Igel und die Maus. In den Filmen wird dem Leben in der Natur auch die Umwelt in der Stadt gegen&uuml;bergestellt, sowie dem naiv-kindlichen Leben der Tiere der Alltag der Menschen. Anfangs sprach der Maulwurf noch, sp&auml;ter nicht mehr, damit er &uuml;berall auf der Welt verstanden wird.\r<br>Seit 1963 war der Maulwurf regelm&auml;&szlig;ig im tschechoslowakischen bzw. sp&auml;ter tschechischen Fernsehen zu sehen. In der tschechischen Originalfassung hei&szlig;t der Maulwurf „Krtek“ (tschech. &quot;Maulwurf&quot;) bzw. „Krtecek“ (tschech. „Maulw&uuml;rfchen“). Er war dort der Star des tschechischen Sandm&auml;nnchens, des Vecernicek. In insgesamt 80 L&auml;ndern der Erde wurde der kleine Maulwurf zum Erfolg. Bekannt wurde die Figur im Westen Deutschlands durch Die Sendung mit der Maus. In einer Videoedition lief er teilweise unter dem Namen „Pauli“. Zuletzt entstand 2002 ein abendf&uuml;llender Zeichentrickfilm des kleinen Maulwurfs; dieser Film ist allerdings nur eine Zusammenstellung aus den ersten zw&ouml;lf Folgen.\r<br>Die Musik wurde von Milos Vacek, ab 1974 von Vadim Petrov komponiert.', '2012-10-25 16:19:12'),
(56, 21, 'die Vernachl&auml;ssigung des Blogs und ihre Folge', 'Mein letzter Blogeintrag ist nun schon sooo lange her, dass ich mich innerlich schon leicht sch&auml;me.\r<br>Aber ich hoffe, dass mir das ganze nicht nachgesehen wird...\r<br>\r<br>Diese Nacht habe ich vom Blog getr&auml;umt... habe getr&auml;umt wie er nach mir ruft und sich nach einem Lebenszeichen von mir sehnt. Ok, das klingt jetzt etwas &quot;strange&quot;, aber es stimmt... Ich wollte mich verteidigen und sagte: &quot;Es tut mir leid, in letzter Zeit hatte ich so viel um die Ohren... Es war richtig stressig in der Hochschule...&quot;. Insgeheim hoffte ich, dass der Blog meinen Semesterplan nicht kannte... Aber ganz so krass h&auml;tte der nicht gegen meine Halbausrede &quot;Stress&quot; gestanden...\r<br>Nunja, das Ende vom Lied war, dass mich der Blog dazu verpflichtet hat, mind. alle zwei Tage einmal vorbei zu schauen und von meinem Alltag zu berichten...\r<br>\r<br>...und mit diesem Eintrag habe ich den Anfang dazu gemacht.', '2012-10-25 17:30:18'),
(58, 33, 'asfsfd', 'dsfasdfasdfasdfasdfdsff\r<br>sdafdsafdsaf\r<br>dsafdasf\r<br>dsafdsafdsa\r<br>fdsaf\r<br>sdaf\r<br>dsaf\r<br>sdaf\r<br>asdf\r<br>\r<br>f', '2012-10-25 17:43:04');

