INSERT INTO `kommentare` (`id`, `blog_id`, `user_id`, `betreff`, `inhalt`, `datum`) VALUES
(2, 39, 22, 'Re: Handeln Sie noch?', 'Ich bin dabei. Seit die EZB bereit ist, alles zu tun um den Euro retten, bin ich wieder eingestiegen.', '2012-10-24 17:01:52'),
